const tokens = $('02a_busca_tokens').all().map(i => i.json);
const painelTokenRow = tokens.find(t => t.service === 'painel_token');
const tokenEsperado = painelTokenRow ? painelTokenRow.signing_secret : null;
const tokenRecebido = $('01_webhook_get').item.json.query.token || '';

return [{
  json: {
    token_valido: !!tokenEsperado && tokenRecebido === tokenEsperado
  }
}];

return [
  { json: { id: 'ptiyq22o4yT5lb1q', nome: '01_Captura_Inicial', janela_horas: 25 } },
  { json: { id: 'EQ3YEDcPysyaFlZp', nome: '03_Geracao_Proposta', janela_horas: 25 } },
  { json: { id: 'a8P2SlOqAoGIgrYB', nome: '04_Regua_Followup', janela_horas: 25 } },
  { json: { id: 'qxRPYOrK5nlZ1Owa', nome: 'Resend_Webhook_Status', janela_horas: 48 } },
  { json: { id: 'l1Ke8AmXHQdkdRl5', nome: 'WhatsApp_Webhook_Status', janela_horas: 48 } },
  { json: { id: 'piESSqN70HqtsGzK', nome: 'RD Station - Renovar Token', janela_horas: 25 } }
];

// Coleta bruta de cada fonte (referência explícita, nunca $json cru - dados vêm de branches paralelas)
const leads = $('03_busca_base_funil').all().map(i => i.json);
const errosLog = $('04_busca_log_erros').all().map(i => i.json);
const tokens = $('02a_busca_tokens').all().map(i => i.json);
const criticos = $('06a_workflows_criticos').all().map(i => i.json);
const execucoes = $('06_busca_execucoes_n8n').all().map(i => i.json);

const agora = new Date();

// ---------- Seção 2: Saúde da Base ----------
const totalLeads = leads.length;
const cabecalhoIntegro = totalLeads > 0 && Object.prototype.hasOwnProperty.call(leads[0], 'lead_id');
const ultimoLead = totalLeads > 0 ? leads[totalLeads - 1] : null;
const ultimoLeadTimestamp = ultimoLead ? (ultimoLead.data_primeiro_contato || null) : null;

// ---------- Token RD Station (usado na Seção 1, card 6, e na Seção 5) ----------
const tokenRD = tokens.find(t => t.service === 'rdstation') || null;
const rdExpiraEm = (tokenRD && tokenRD.expires_at) ? new Date(tokenRD.expires_at) : null;
const rdDiasParaExpirar = (rdExpiraEm && !isNaN(rdExpiraEm)) ? (rdExpiraEm - agora) / (1000 * 60 * 60 * 24) : null;

// ---------- Seção 1: Status dos Workflows Críticos ----------
const statusWorkflows = criticos.map((c, idx) => {
  const resp = execucoes[idx] || {};
  const lista = resp.data || [];
  const ultima = lista[0] || null;

  let status, horasDesde, motivo;

  if (!ultima) {
    status = 'problema';
    horasDesde = null;
    motivo = 'nunca executou';
  } else {
    const inicio = new Date(ultima.startedAt);
    horasDesde = (agora - inicio) / (1000 * 60 * 60);
    const falhou = ultima.status === 'error';
    const excedeuJanela = horasDesde > c.janela_horas;

    if (falhou || excedeuJanela) {
      // janela de 25h = severidade vermelha; janela de 48h = severidade amarela
      status = c.janela_horas <= 25 ? 'problema' : 'atencao';
      motivo = falhou ? 'última execução falhou' : `não executou nas últimas ${c.janela_horas}h`;
    } else {
      status = 'ok';
      motivo = `última execução há ${horasDesde.toFixed(1)}h`;
    }
  }

  // Card do RD Station também reflete a validade do token (pode agravar o status, nunca melhorar)
  let detalheToken = '';
  if (c.nome === 'RD Station - Renovar Token') {
    if (rdDiasParaExpirar === null) {
      status = 'problema';
      detalheToken = ' | token RD Station não encontrado na aba tokens';
    } else if (rdDiasParaExpirar < 0) {
      status = 'problema';
      detalheToken = ` | token RD Station expirado há ${Math.abs(rdDiasParaExpirar).toFixed(1)} dias`;
    } else if (rdDiasParaExpirar < 2) {
      status = 'problema';
      detalheToken = ` | token RD Station expira em ${rdDiasParaExpirar.toFixed(1)} dias`;
    } else {
      detalheToken = ` | token RD Station expira em ${rdDiasParaExpirar.toFixed(1)} dias`;
    }
  }

  return {
    nome: c.nome,
    status,
    motivo: motivo + detalheToken
  };
});

// ---------- Seção 3: Funil em Tempo Real ----------
const funilEtapas = ['Novo Lead', 'Proposta Enviada', 'Em Follow-up', 'Ganho', 'Perdido'];
const funilContagem = funilEtapas.map(etapa => ({
  etapa,
  contagem: leads.filter(l => l.status_funil === etapa).length
}));

const ultimos5Leads = leads.slice(-5).reverse().map(l => ({
  nome: l.nome_contato || l.razao_social || '(sem nome)',
  empresa: l.razao_social || '',
  status: l.status_funil || '',
  ultimo_toque: l.ultimo_toque_data || l.data_primeiro_contato || ''
}));

const leadCapturadoHoje = leads.some(l => {
  if (!l.data_primeiro_contato) return false;
  const d = new Date(l.data_primeiro_contato);
  return !isNaN(d) && d.toDateString() === agora.toDateString();
});

// ---------- Seção 4: Log de Erros Recentes ----------
const ultimosErros = errosLog.slice(-10).reverse().map(e => ({
  timestamp: e.timestamp || '',
  workflow: e.workflow || '',
  mensagem: e.mensagem_erro || '',
  link: e.link_execucao || ''
}));

const erros24h = errosLog.filter(e => {
  const t = new Date(e.timestamp);
  return !isNaN(t) && (agora - t) <= 24 * 60 * 60 * 1000;
});

// ---------- Seção 5: Alertas Ativos (5 regras, ordenadas por severidade) ----------
const alertas = [];

// Regra 1 (🔴): token RD Station expira em menos de 2 dias
if (rdDiasParaExpirar !== null && rdDiasParaExpirar < 2) {
  const txt = rdDiasParaExpirar < 0
    ? `Token RD Station expirado há ${Math.abs(rdDiasParaExpirar).toFixed(1)} dias`
    : `Token RD Station expira em ${rdDiasParaExpirar.toFixed(1)} dias`;
  alertas.push({ severidade: 'vermelho', texto: txt });
}

// Regra 2 (🔴): workflow de janela 25h não executou (ou falhou, ou nunca rodou)
statusWorkflows.forEach(w => {
  const c = criticos.find(x => x.nome === w.nome);
  if (c && c.janela_horas <= 25 && w.status === 'problema' && w.nome !== 'RD Station - Renovar Token') {
    alertas.push({ severidade: 'vermelho', texto: `Workflow ${w.nome}: ${w.motivo} (janela de 25h)` });
  }
});

// Regra 3 (🔴): cabeçalho da base corrompido
if (!cabecalhoIntegro) {
  alertas.push({ severidade: 'vermelho', texto: 'Cabeçalho da base_funil_completo corrompido (coluna A não é lead_id) — possível bug de aba trocada' });
}

// Regra 4 (🟡): workflow de janela 48h não executou
statusWorkflows.forEach(w => {
  const c = criticos.find(x => x.nome === w.nome);
  if (c && c.janela_horas > 25 && w.status !== 'ok') {
    alertas.push({ severidade: 'amarelo', texto: `Workflow ${w.nome}: ${w.motivo} (janela de 48h)` });
  }
});

// Regra 5 (🟡): nenhum lead capturado hoje
if (!leadCapturadoHoje) {
  alertas.push({ severidade: 'amarelo', texto: 'Nenhum lead capturado hoje' });
}

// ordena: vermelho antes de amarelo
alertas.sort((a, b) => (a.severidade === b.severidade ? 0 : a.severidade === 'vermelho' ? -1 : 1));

return [{
  json: {
    gerado_em: agora.toISOString(),
    secao1_status_workflows: statusWorkflows,
    secao2_saude_base: {
      total_leads: totalLeads,
      cabecalho_integro: cabecalhoIntegro,
      ultimo_lead_timestamp: ultimoLeadTimestamp
    },
    secao3_funil: {
      etapas: funilContagem,
      ultimos_5_leads: ultimos5Leads
    },
    secao4_log_erros: {
      total_erros_24h: erros24h.length,
      banner_verde: erros24h.length === 0,
      ultimos_erros: ultimosErros
    },
    secao5_alertas: alertas
  }
}];

const d = $('07_consolida_dados').item.json;

const CORES = {
  indigo: '#3A34D6',
  petroleo: '#12786B',
  ambar: '#D9822B',
  vermelho: '#DC2626',
  warmWhite: '#F7F5F1',
  grafite: '#1B1E27'
};

const SHEET_URL_BASE = 'https://docs.google.com/spreadsheets/d/1hN8tekfac-2MQI4YoR7KuVRdd2YmnlGJM62drLdHtfs/edit#gid=810524007';

function escapeHtml(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatDataHora(iso) {
  if (!iso) return '—';
  const dt = new Date(iso);
  if (isNaN(dt)) return String(iso);
  return dt.toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' });
}

function iconeStatus(status) {
  if (status === 'ok') return '🟢';
  if (status === 'atencao') return '🟡';
  return '🔴';
}

// ---------- Seção 1: Status dos Workflows Críticos ----------
function renderSecao1(statusWorkflows) {
  const linhas = statusWorkflows.map(w => `
    <tr>
      <td>${iconeStatus(w.status)}</td>
      <td><strong>${escapeHtml(w.nome)}</strong></td>
      <td>${escapeHtml(w.motivo)}</td>
    </tr>`).join('');

  return `
  <section class="card">
    <h2>Status dos Workflows Críticos</h2>
    <p class="subtitulo">Algum workflow parou?</p>
    <table>
      <thead><tr><th></th><th>Workflow</th><th>Situação</th></tr></thead>
      <tbody>${linhas}</tbody>
    </table>
  </section>`;
}

// ---------- Seção 2: Saúde da Base ----------
function renderSecao2(saude) {
  return `
  <section class="card">
    <h2>Saúde da Base</h2>
    <p class="subtitulo">Os dados estão íntegros?</p>
    <div class="indicadores-linha">
      <div class="indicador">
        <span class="indicador-icone">${saude.total_leads > 0 ? '🟢' : '🔴'}</span>
        <span class="indicador-valor">${saude.total_leads}</span>
        <span class="indicador-label">leads na base</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">${saude.cabecalho_integro ? '🟢' : '🔴'}</span>
        <span class="indicador-valor">${saude.cabecalho_integro ? 'OK' : 'Corrompido'}</span>
        <span class="indicador-label">cabeçalho (coluna A = lead_id)</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">🕒</span>
        <span class="indicador-valor">${formatDataHora(saude.ultimo_lead_timestamp)}</span>
        <span class="indicador-label">último lead capturado</span>
      </div>
    </div>
  </section>`;
}

// ---------- Seção 3: Funil em Tempo Real ----------
function renderSecao3(funil) {
  const maxContagem = Math.max(1, ...funil.etapas.map(e => e.contagem));
  const miniFunil = funil.etapas.map(e => `
    <div class="funil-etapa">
      <div class="funil-barra" style="height:${8 + (e.contagem / maxContagem) * 60}px;"></div>
      <div class="funil-contagem">${e.contagem}</div>
      <div class="funil-label">${escapeHtml(e.etapa)}</div>
    </div>`).join('');

  const linhasLeads = funil.ultimos_5_leads.map(l => `
    <tr class="linha-clicavel" onclick="window.open('${SHEET_URL_BASE}', '_blank')">
      <td>${escapeHtml(l.nome)}</td>
      <td>${escapeHtml(l.empresa)}</td>
      <td>${escapeHtml(l.status)}</td>
      <td>${formatDataHora(l.ultimo_toque)}</td>
    </tr>`).join('') || '<tr><td colspan="4">Nenhum lead na base ainda.</td></tr>';

  return `
  <section class="card">
    <h2>Funil em Tempo Real</h2>
    <p class="subtitulo">Como está o pipeline hoje?</p>
    <div class="mini-funil">${miniFunil}</div>
    <table>
      <thead><tr><th>Nome</th><th>Empresa</th><th>Status</th><th>Último toque</th></tr></thead>
      <tbody>${linhasLeads}</tbody>
    </table>
  </section>`;
}

// ---------- Seção 4: Log de Erros Recentes ----------
function renderSecao4(log) {
  const banner = log.banner_verde
    ? `<div class="banner banner-verde">Nenhum erro nas últimas 24h ✅</div>`
    : `<div class="banner banner-vermelho">${log.total_erros_24h} erro(s) nas últimas 24h 🚨</div>`;

  const linhas = log.ultimos_erros.map(e => `
    <tr>
      <td>${formatDataHora(e.timestamp)}</td>
      <td>${escapeHtml(e.workflow)}</td>
      <td>${escapeHtml(e.mensagem)}</td>
      <td>${e.link ? `<a href="${escapeHtml(e.link)}" target="_blank">Ver execução</a>` : '—'}</td>
    </tr>`).join('') || '<tr><td colspan="4">Sem registros na aba log_erros_producao.</td></tr>';

  return `
  <section class="card">
    <h2>Log de Erros Recentes</h2>
    <p class="subtitulo">Teve algum erro nas últimas 24h?</p>
    ${banner}
    <table>
      <thead><tr><th>Horário</th><th>Workflow</th><th>Erro</th><th>Execução</th></tr></thead>
      <tbody>${linhas}</tbody>
    </table>
  </section>`;
}

// ---------- Seção 5: Alertas Ativos ----------
function renderSecao5(alertas) {
  if (!alertas || alertas.length === 0) return '';
  const linhas = alertas.map(a => `
    <li class="alerta alerta-${a.severidade}">
      ${a.severidade === 'vermelho' ? '🔴' : '🟡'} ${escapeHtml(a.texto)}
    </li>`).join('');

  return `
  <section class="card">
    <h2>Alertas Ativos</h2>
    <p class="subtitulo">Tem algo que preciso resolver agora?</p>
    <ul class="lista-alertas">${linhas}</ul>
  </section>`;
}

const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Painel Operacional — Funil Antere</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
<style>
  :root {
    --indigo: ${CORES.indigo};
    --petroleo: ${CORES.petroleo};
    --ambar: ${CORES.ambar};
    --vermelho: ${CORES.vermelho};
    --warm-white: ${CORES.warmWhite};
    --grafite: ${CORES.grafite};
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: 'Inter', Arial, sans-serif;
    background: var(--warm-white);
    color: var(--grafite);
  }
  header {
    background: var(--indigo);
    color: #fff;
    padding: 24px 40px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
  }
  header .logo-bloco .logo { font-size: 22px; font-weight: 700; letter-spacing: -0.5px; }
